<?php
declare(strict_types=1);
namespace Nexus\Features\Trabajo\Infrastructure;
use Nexus\Features\Trabajo\Domain\TrabajoRepository;use Nexus\Shared\Domain\ValueObject\Cedula;
final class PdoTrabajoRepository implements TrabajoRepository
{
    private \PDO $pdo;public function __construct(\PDO $p){$this->pdo=$p;}
    public function listarTareas():array{$q=$this->pdo->query('SELECT t.id_tarea,t.titulo_tarea,t.descripcion_tarea,t.plazo_tarea,t.categoria_tarea,t.dificultad_tarea,t.estado_tarea,t.color_tarea,t.fecha_agregada,MIN(rt.cedula) tecnico_cedula FROM TAREAS t LEFT JOIN REALIZA_TAREA rt ON rt.id_tarea=t.id_tarea GROUP BY t.id_tarea,t.titulo_tarea,t.descripcion_tarea,t.plazo_tarea,t.categoria_tarea,t.dificultad_tarea,t.estado_tarea,t.color_tarea,t.fecha_agregada ORDER BY t.plazo_tarea,t.id_tarea DESC');return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function responsableValido(?Cedula $c):bool{if($c===null)return true;$q=$this->pdo->prepare("SELECT 1 FROM USUARIO WHERE cedula=? AND estado='Activo' AND rol IN ('Tecnico_Asistente','Administrador')");$q->execute([$c->value()]);return (bool)$q->fetchColumn();}
    public function crearTarea(array $d,?Cedula $c):int{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('INSERT INTO TAREAS(titulo_tarea,descripcion_tarea,plazo_tarea,categoria_tarea,dificultad_tarea,estado_tarea,color_tarea,fecha_agregada) VALUES(?,?,?,?,?,?,?,CURDATE())');$q->execute([$d['titulo'],$d['descripcion'],$d['plazo'],$d['categoria'],$d['prioridad'],$d['estado'],$d['color']]);$id=(int)$this->pdo->lastInsertId();if($c){$q=$this->pdo->prepare('INSERT INTO REALIZA_TAREA(cedula,id_tarea) VALUES(?,?)');$q->execute([$c->value(),$id]);}$this->pdo->commit();return $id;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function actualizarTarea(int $id,array $d,?Cedula $c):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('SELECT 1 FROM TAREAS WHERE id_tarea=? FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn()){$this->pdo->rollBack();return false;}$q=$this->pdo->prepare('UPDATE TAREAS SET titulo_tarea=?,descripcion_tarea=?,plazo_tarea=?,categoria_tarea=?,dificultad_tarea=?,estado_tarea=?,color_tarea=? WHERE id_tarea=?');$q->execute([$d['titulo'],$d['descripcion'],$d['plazo'],$d['categoria'],$d['prioridad'],$d['estado'],$d['color'],$id]);$q=$this->pdo->prepare('DELETE FROM REALIZA_TAREA WHERE id_tarea=?');$q->execute([$id]);if($c){$q=$this->pdo->prepare('INSERT INTO REALIZA_TAREA(cedula,id_tarea) VALUES(?,?)');$q->execute([$c->value(),$id]);}$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function eliminarTarea(int $id):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('SELECT 1 FROM TAREAS WHERE id_tarea=? FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn()){$this->pdo->rollBack();return false;}$q=$this->pdo->prepare('DELETE FROM REALIZA_TAREA WHERE id_tarea=?');$q->execute([$id]);$q=$this->pdo->prepare('DELETE FROM TAREAS WHERE id_tarea=?');$q->execute([$id]);$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function listarPlanillas():array{$q=$this->pdo->query("SELECT p.id_plantilla,u.cedula,p.comentario_ta,p.horario_entrada_ta,p.horario_salida_ta FROM USUARIO u LEFT JOIN PLANTILLA_TECNICO_ASISTENTE p ON p.cedula=u.cedula WHERE u.esta_activo=1 AND u.estado='Activo' AND u.rol IN ('Tecnico_Asistente','Administrador') ORDER BY u.rol='Administrador' DESC,u.nombre,u.apellido");return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function guardarPlanilla(Cedula $c,array $d):void{$q=$this->pdo->prepare('INSERT INTO PLANTILLA_TECNICO_ASISTENTE(cedula,comentario_ta,horario_entrada_ta,horario_salida_ta) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE comentario_ta=VALUES(comentario_ta),horario_entrada_ta=VALUES(horario_entrada_ta),horario_salida_ta=VALUES(horario_salida_ta)');$q->execute([$c->value(),$d['tareas'],$d['entrada'],$d['salida']]);}
}
